 # -*- coding: utf-8 -*-"""Name: Anatoliy LevchukVersion: 1.6Date: 10-02-2026Email: feuerlag999@yandex.ruGitHub: https://github.com/LeTond"""import osimport sysimport cv2import yamlimport torchimport platformimport numpy as npimport pandas as pdimport torch.nn.functional as Fimport torchvision.transforms as transformsimport torchvision.transforms.functional as TFfrom torch import nnfrom torchsummary import summaryimport CardioCascadeNetclass MetaParameters:    _root_directory_path = os.path.abspath(os.path.dirname('..'))    config_path = f"{_root_directory_path}/config.yml"    with open(config_path, 'r') as stream:        _project_config = yaml.safe_load(stream)['almaz_model']['project_config']    with open(config_path, 'r') as stream:        _meta_config = yaml.safe_load(stream)['almaz_model']['meta']    with open(config_path, 'r') as stream:        _hyperparams = yaml.safe_load(stream)['almaz_model']['network_hyperparams']    """ Initializing project configuration """    PROJECT_NAME, DATASET_NAME, FOLD_NAME = _project_config.values()        DATASET_DIR = f"{_root_directory_path}/Dataset/"    RESULTS_DIR = f"{_root_directory_path}/Results/"    PROJ_NAME = f"{_root_directory_path}/{PROJECT_NAME}/Model/{DATASET_NAME}"    IMAGES_DIR = f'{DATASET_DIR}{DATASET_NAME}_images'    MASKS_DIR = f'{DATASET_DIR}{DATASET_NAME}_masks'    """ Initializing meta """    FREEZE_BN, PRETRAIN, AUGMENTATION, NOISE, EMPTY, MULTYGAP, \    UNET1, UNET2, UNET3, UNET4, UNET5, BGCROPP, LVCROPP, BGLVCROPP, SHUFFLE = _meta_config.values()    # AUGMENTATION = True    UNET1 = True    UNET2 = True    # UNET3 = True    # UNET4 = True    # UNET5 = True    PDF_FLAG_UNET1 = False    PDF_FLAG_UNET2 = False    PDF_FLAG_UNET3 = False    PDF_FLAG_UNET4 = False    PDF_FLAG_UNET5 = False    """ Initializing network_hyperparams """    KERNEL, CROPP_KERNEL, CHANNELS, LR, BT_SZ, EPOCHS, DROPOUT, FEATURES, \    WDC, EARLY_STOPPING, TMAX, CLIP_RATE, \    SCAR_DICT_CLASS, MYOLEVEL_DICT_CLASS, BULLEYE_DICT_CLASS = _hyperparams.values()    CLIP_RATE = None    if UNET5 is True:        DICT_CLASS = BULLEYE_DICT_CLASS      elif UNET4 is True and UNET5 is False:        DICT_CLASS = MYOLEVEL_DICT_CLASS    elif UNET3 is True and UNET4 is False:        DICT_CLASS = SCAR_DICT_CLASS    elif UNET2 is True and UNET3 is False:        DICT_CLASS = SCAR_DICT_CLASS    elif UNET1 is True and UNET2 is False:        DICT_CLASS = SCAR_DICT_CLASS    NUM_CLASS = len(DICT_CLASS)    """ New directory paths """    UNET1_FOLD = f'Unet1_Fold_{FOLD_NAME}/'    UNET2_FOLD = f'Unet2_Fold_{FOLD_NAME}/'    UNET3_FOLD = f'Unet3_Fold_{FOLD_NAME}/'    UNET4_FOLD = f'Unet4_Fold_{FOLD_NAME}/'    UNET5_FOLD = f'Unet5_Fold_{FOLD_NAME}/'    NEW_DATA_PATH = f'{DATASET_DIR}{DATASET_NAME}_images_new/'    NEW_UNET1_MASKS_PATH = f'{RESULTS_DIR}{DATASET_NAME}_Unet1_masks_new/'    NEW_UNET2_MASKS_PATH = f'{RESULTS_DIR}{DATASET_NAME}_Unet2_masks_new/'    NEW_UNET3_MASKS_PATH = f'{RESULTS_DIR}{DATASET_NAME}_Unet3_masks_new/'    NEW_UNET4_MASKS_PATH = f'{RESULTS_DIR}{DATASET_NAME}_Unet4_masks_new/'    NEW_UNET5_MASKS_PATH = f'{RESULTS_DIR}{DATASET_NAME}_Unet5_masks_new/'class ChooseDevice:    def __init__(self):        self.print_device    @staticmethod    def __device():        if torch.backends.mps.is_available():            device = torch.device('mps')        elif torch.cuda.is_available():            device = torch.device('cuda')        else:            device = torch.device('cpu')        return device    @property    def device(self):        return self.__device()    @property    def print_device(self):        print(self.device)class FocalLoss(nn.modules.loss._WeightedLoss):    def __init__(self, weight = None, gamma = 2, reduction = 'mean'):    #reduction='sum'        super(FocalLoss, self).__init__(weight,reduction = reduction)        self.gamma = gamma        self.weight = weight    def forward(self, input, target):        ce_loss = F.cross_entropy(input, target, reduction = self.reduction,weight = self.weight)        pt = torch.exp( - ce_loss)        focal_loss = ((1 - pt) ** self.gamma * ce_loss).mean()        return focal_lossclass ChooseTypeMatrix(MetaParameters):    def __init__(self, files = None, augmentation = None):        super().__init__()            def unet_type(self):        if self.UNET5 is True:            return 'cropp'        elif self.UNET4 is True and self.UNET5 is False:            return 'cropp'        elif self.UNET3 is True and self.UNET4 is False:            return 'close_cropp'        elif self.UNET2 is True and self.UNET3 is False:            return 'cropp'        elif self.UNET1 is True and self.UNET2 is False:            return 'default'        else:            raise ValueError     def mask_type(self):        if self.BGCROPP is True:            return 'bgcropp'        elif self.LVCROPP is True:            return 'lvcropp'        elif self.BGLVCROPP is True:            return 'bglvcropp'        elif self.UNET4 is True and self.UNET5 is False:            return 'lv_level'        elif self.UNET5 is True:            return 'train_bull_level'        else:            return Noneclass ChooseKernelSize(MetaParameters):    def __init__(self):            super().__init__()    def matrix_size(self, unet_type = None):        if unet_type is None:            if self.UNET5 is True:                return 'cropp'            elif self.UNET4 is True and self.UNET5 is False:                return 'cropp'            elif self.UNET3 is True and self.UNET4 is False:                return 'close_cropp'            elif self.UNET2 is True and self.UNET3 is False:                return 'cropp'            elif self.UNET1 is True and self.UNET2 is False:                return 'default'            else:                 raise ValueError("Check UNET configuration. Make shure that all UNET MetaParameters before target UNET(N) is True")        else:            return unet_type    def kernel_size(self, unet_type = None):        matrix_size = self.matrix_size(unet_type)        if matrix_size == 'default':            return self.KERNEL        elif matrix_size == 'cropp':            return self.CROPP_KERNEL        elif matrix_size == 'close_cropp':            return self.CROPP_KERNEL        else:            raise ValueError("Check matrix size value. Make shure that input value is correct for chosen matrix preprocessing")class ChooseModelConfig(MetaParameters):    def __init__(self):            super(MetaParameters, self).__init__()        self.__model = self.choose_train_model      @property    def model(self):        return self.__model    @property    def choose_model_key(self):        if self.UNET5 is True:            return self.UNET5_FOLD        elif self.UNET4 is True and self.UNET5 is False:            return self.UNET4_FOLD        elif self.UNET3 is True and self.UNET4 is False:            return self.UNET3_FOLD        elif self.UNET2 is True and self.UNET3 is False:            return self.UNET2_FOLD        elif self.UNET1 is True and self.UNET2 is False:            return self.UNET1_FOLD        else:            raise ValueError("Check UNET configuration. Make shure that all UNET MetaParameters before target UNET(N) is True")    def model_key(self):        return self.choose_model_key    @property    def choose_train_model(self):        if self.PRETRAIN:                try:                checkpoint = torch.load(f"{self.PROJ_NAME}/{self.DATASET_NAME}_model.pth")                # checkpoint = torch.load(f'{self.PROJ_NAME}/{self.DATASET_NAME}_model.pth', map_location = torch.device('cpu'))                checkpoint = checkpoint[f"Net_{self.DATASET_NAME}_{self.model_key}"]                model = checkpoint['Model']                model.load_state_dict(checkpoint['weights'])                  model.eval()                      print(f'model loaded: {self.DATASET_NAME}_model.pth')            except:                print('no trained models')                model = CardioCascadeNet.UNet_2D_AttantionLayer().to(device = device)                else:            model = CardioCascadeNet.UNet_2D_AttantionLayer().to(device = device)            # model = CardioCascadeNet.UNet_2D().to(device=device)            # model = CardioCascadeNet.UNetResnet().to(device=device)            # model = CardioCascadeNet.SegNet().to(device=device)            # model = CardioCascadeNet.ResNet().to(device=device)            # model = CardioCascadeNet.SwinUNet().to(device = device)            # model = CardioCascadeNet.R2AttU_Net().to(device = device)                return model    def summary_params(self):        summary(self.choose_train_model, input_size = (2, 64, 64))    @property    def freeze_model_bn(self):        if self.FREEZE_BN is True:            for name, child in self.model.named_children():                 if name in ['decoder4', 'upconv4', 'Att4', 'decoder3', 'upconv3', 'Att3', 'decoder2', 'upconv2', 'Att2', 'decoder1', 'upconv1', 'Att1', 'conv']:                    print(name + ' has been unfrozen.')                     for param in child.parameters():                         param.requires_grad = True                 else:                     for param in child.parameters():                         param.requires_grad = False        # optimizer = torch.optim.Adam(self.model.parameters(), lr = self.LR, weight_decay = self.WDC)        # optimizer = torch.optim.AdamW(self.model.parameters(), lr = self.LR, weight_decay = self.WDC)        # optimizer = torch.optim.AdamW(self.model.parameters(), lr = self.LR, weight_decay = self.WDC, amsgrad = False)        # optimizer = torch.optim.AdamW(self.model.parameters(), betas = (0.9, 0.999), eps = 1e-5, foreach = None, differentiable = False, fused = None, lr = self.LR, weight_decay = self.WDC, amsgrad = False)                # optimizer = torch.optim.SGD(self.model.parameters(), lr = self.LR, weight_decay = self.WDC, momentum = 0.9, nesterov = True)                optimizer = CardioCascadeNet.Ranger(self.model.parameters(), lr = self.LR, k = 6, N_sma_threshhold = 5, weight_decay = self.WDC)        # optimizer = CardioCascadeNet.Ranger(filter(lambda x: x.requires_grad, self.model.parameters()),  lr = self.LR, k = 6, N_sma_threshhold = 5, weight_decay = self.WDC)        # optimizer = CardioCascadeNet.Lion(self.model.parameters(), lr = self.LR, betas = (0.9, 0.99), weight_decay = self.WDC)        return optimizer    @property    def optimizer(self):        return self.freeze_model_bn    @property    def choose_scheduler_gen(self):        scheduler_gen = torch.optim.lr_scheduler.CosineAnnealingLR(            self.optimizer, T_max = self.TMAX, eta_min = 0, last_epoch = -1, verbose = True)        return scheduler_gen    @property    def scheduler_gen(self):        return self.choose_scheduler_gen    @staticmethod    def rewrite_weights(from_model, to_model, unet_model):        _root_directory_path = os.path.abspath(os.path.dirname('..'))        checkpoint1 = torch.load(f"{_root_directory_path}/CardioCascadeNet/Model/{from_model}/{from_model}_model.pth")        checkpoint1 = checkpoint1[f'Net_{from_model}_{unet_model}']                checkpoint = torch.load(f"{_root_directory_path}/CardioCascadeNet/Model/{to_model}/{to_model}_model.pth")        checkpoint[f'Net_{to_model}_{unet_model}'] = {'Model': checkpoint1['Model'], 'weights': checkpoint1['Model'].state_dict()}                torch.save(            checkpoint,            f"{_root_directory_path}/CardioCascadeNet/Model/{to_model}/{to_model}_model.pth")        print(f'weights was pull from {from_model} and drop to {to_model}')class ChooseLossFunction(MetaParameters):    def __init__(self, loss_weights: list = None):        super(MetaParameters, self).__init__()        self.loss_weights = torch.FloatTensor(loss_weights)        self.print_loss_function()    @property    def choose_loss_function(self):        try:            loss_function = nn.CrossEntropyLoss(weight = self.loss_weights).to(device)                            return loss_function        except:            loss_function = FocalLoss().to(device)                        return loss_function    @property    def loss_function(self):        return self.choose_loss_function    def print_loss_function(self):        if self.loss_function is not None:        # if self.CE_WEIGHTS is not None:            # print(f'{self.loss_function} With {self.CE_WEIGHTS} Was Chosen !!!')            print(f'{self.loss_function} With {self.loss_weights} Was Chosen !!!')        else:                        print(f'{self.loss_function} without CE_WEIGHTS Was Chosen !!!')            # print(f'{self.loss_function} With {self.loss_weights} Was Chosen !!!')class ChooseTransform(MetaParameters):    def __init__(self):        super(MetaParameters, self).__init__()    @classmethod    def choose_transforms(cls, transform):        transform_01 = transforms.Compose([            transforms.ToPILImage(),            transforms.ToTensor(),        ])        transform_02 = transforms.Compose([            transforms.ToPILImage(),            transforms.RandomRotation((-5, 5), expand = False),            transforms.RandomHorizontalFlip(0.5),            transforms.RandomVerticalFlip(0.5),            transforms.ToTensor(),        ])        transform_03 = transforms.Compose([            transforms.ToPILImage(),            transforms.RandomHorizontalFlip(0.5),            transforms.RandomVerticalFlip(0.5),            transforms.RandomAffine(degrees = (-2, 2), translate = (0.05, 0.15), scale = (0.95, 1.05)),            transforms.ToTensor(),        ])        transform_04 = transforms.Compose([            transforms.ToPILImage(),            transforms.RandomRotation((-5, 5), expand = False),            transforms.RandomHorizontalFlip(0.5),            transforms.RandomVerticalFlip(0.5),            transforms.RandomAffine(degrees = (-8, 8), translate = (0.05, 0.15), scale = (0.9, 1.1)),            transforms.ToTensor(),        ])        transform_dict = {        'transform_01': transform_01, 'transform_02': transform_02,         'transform_03': transform_03, 'transform_04': transform_04        }        return transform_dict[transform]device = ChooseDevice().deviceprint(f"Python Platform: {platform.platform()}")print(f'python version: {sys.version}')print(f'torch version: {torch.__version__}')print(f'numpy version: {np.__version__}')print(f'pandas version: {pd.__version__}')